import { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { SpatialRuntime, spatialPoolStats } from '../../src/components/spatial/spatialRuntime';
import { createPrevisRenderer } from '../../src/components/spatial/previsRenderer';
import { spatialClient, composeStudio } from '../../src/clients/spatialClient';
import type { PrevisWorldPlan } from '../../src/clients/previsClient';
export function SpatialBenchmark(){const host=useRef<HTMLDivElement>(null),[report,setReport]=useState<any>({status:'运行中'});useEffect(()=>{let stopped=false;const renderer=createPrevisRenderer(1920,1080);host.current!.appendChild(renderer.domElement);let runtime:SpatialRuntime|undefined;void(async()=>{try{const district=new URLSearchParams(location.search).has('district');const {studio}=await spatialClient.studio(district?'qingshui-district':'sample-ancient');let world:PrevisWorldPlan={schemaVersion:'previs-world.v1',title:'实例化与释放验收',description:'',locations:[],objects:[]};if(district)world=studio.plan;else for(let i=0;i<60;i++)world=composeStudio(world,studio,`bench-${i}`,[(i%10)*48,0,Math.floor(i/10)*65]);const started=performance.now();runtime=new SpatialRuntime(world);const camera=new THREE.PerspectiveCamera(45,1920/1080,.05,10000);camera.position.set(210,140,300);camera.lookAt(220,0,150);await runtime.prepare(camera);await renderer.compileAsync(runtime.scene,camera);const coldLoadMs=performance.now()-started;const gl=renderer.getContext(),extension=gl.getExtension('WEBGL_debug_renderer_info');const device={browser:navigator.userAgent,gpu:extension?gl.getParameter(extension.UNMASKED_RENDERER_WEBGL):'unavailable'};const frames:number[]=[],memory:any[]=[],loads:number[]=[];let last=performance.now(),begin=last;
for(let frame=0;!stopped&&(district?performance.now()-begin<90000:frame<360);frame++){await new Promise<void>(r=>requestAnimationFrame(()=>r()));if(district){const t=(performance.now()-begin)/1000%30;if(t<20){camera.position.set(3,1.7,145-t*9);camera.lookAt(10,2,-180);}else{camera.position.set(98,1.7,-55-(t-20)*5.7);camera.lookAt(98,1.7,-120);}}else{camera.position.x=210+Math.sin(frame/100)*70;camera.lookAt(220,0,150);}if(frame%60===0){const start=performance.now();void runtime.prepare(camera).then(()=>loads.push(performance.now()-start));}runtime.update();renderer.render(runtime.scene,camera);const now=performance.now();if(now-begin>5000)frames.push(now-last);last=now;}

await runtime.prepare(camera);const triangles=renderer.info.render.triangles,drawCalls=renderer.info.render.calls;for(let i=0;i<20&&!stopped;i++){const next=new SpatialRuntime(world);await next.prepare(camera);next.update();renderer.render(next.scene,camera);runtime.dispose();runtime=next;memory.push({...renderer.info.memory,pool:spatialPoolStats()});}
const diagnostics={...runtime.diagnostics};const sorted=frames.sort((a,b)=>a-b);runtime.dispose();runtime=undefined;await new Promise<void>(r=>setTimeout(r,0));renderer.render(new THREE.Scene(),camera);
const result={status:'完成',device,coldLoadMs,loadMs:loads,diagnostics,instances:world.objects.length,locations:world.locations.length,triangles,drawCalls,frames:frames.length,medianMs:sorted[Math.floor(sorted.length*.5)],p95Ms:sorted[Math.floor(sorted.length*.95)],p99Ms:sorted[Math.floor(sorted.length*.99)],twentySwitches:memory,afterRelease:{...renderer.info.memory,pool:spatialPoolStats()}};if(!stopped)setReport(result);
}catch(e){setReport({status:'失败',error:String(e)});}})();return()=>{stopped=true;runtime?.dispose();renderer.dispose();renderer.forceContextLoss();renderer.domElement.remove();};},[]);return <div className="p-4 text-white"><h1>真实结构模型性能验收 · 1920×1080 · DPR 1</h1><div ref={host}/><pre id="benchmark-report">{JSON.stringify(report,null,2)}</pre></div>;}
